// No orphan words. After the build, bind the last two words of each heading, paragraph, list item and summary
// with a no-break space, so one word never sits alone on the last line. CSS `text-wrap: balance` and `pretty`
// (src/styles/site.css) do the rest. design.html is generated by `npm run design -- build`, so it is skipped.
import { readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const LAST_TWO_WORDS = /(\S+)[ \t\n]+([^\s<>]+)((?:<\/(?:em|strong|b|i|a|span|code)>)*<\/(?:h[1-4]|p|li|summary|figcaption)>)/g;

export function bindLastWords(html) {
  return html.replace(LAST_TWO_WORDS, (_all, a, b, tail) => `${a}&nbsp;${b}${tail}`);
}

export default function noOrphans() {
  return {
    name: "no-orphans",
    hooks: {
      "astro:build:done": async ({ dir }) => {
        const root = fileURLToPath(dir);
        for (const name of await readdir(root)) {
          if (!name.endsWith(".html") || name === "design.html") continue;
          const file = join(root, name);
          const html = await readFile(file, "utf8");
          const next = bindLastWords(html);
          if (next !== html) await writeFile(file, next);
        }
      }
    }
  };
}
